//refAssemblies: TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using Microsoft.EntityFrameworkCore;
using TCAdmin.Web.Shared.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// The server rewrites server.ini with its in-memory settings on every save (autosave, /save, /stop), so a change
// made in the config editor while it runs would be lost. Before each start the settings of the config editor are
// written into server.ini again; settings without an editor field keep what the server wrote.
string root = (string)ThisService.RootDirectory;
string galaxy = Path.Combine(root, "galaxies", "avorion_galaxy");
string ini = Path.Combine(galaxy, "server.ini");
bool galaxyExisted = Directory.Exists(galaxy);
Directory.CreateDirectory(galaxy);
if (!galaxyExisted) Own(galaxy);
bool started = Directory.GetFiles(galaxy, "server.dat*").Any();

// (section, key, service variable) - generated from the server.ini template.
var managed = new List<(string Section, string Key, string Variable)>
{
    ("Game", "Scenario", "Scenario"),
    ("Game", "Seed", "Seed"),
    ("Game", "Difficulty", "Difficulty"),
    ("Game", "HardcoreEnabled", "HardcoreEnabled"),
    ("Game", "InfiniteResources", "InfiniteResources"),
    ("Game", "PlayTutorial", "PlayTutorial"),
    ("Game", "CollisionDamage", "CollisionDamage"),
    ("Game", "PlayerToPlayerDamage", "PlayerToPlayerDamage"),
    ("Game", "LogoutInvincibility", "LogoutInvincibility"),
    ("Game", "LogoutInvincibilityDelay", "LogoutInvincibilityDelay"),
    ("Game", "Barrier", "Barrier"),
    ("Game", "Storyline", "Storyline"),
    ("Game", "BehemothEvents", "BehemothEvents"),
    ("Game", "BigWreckageDespawnTime", "BigWreckageDespawnTime"),
    ("Game", "SmallWreckageDespawnTime", "SmallWreckageDespawnTime"),
    ("Game", "MaximumFightersPerSectorAndPlayer", "MaximumFightersPerSectorAndPlayer"),
    ("Game", "MaximumBlocksPerCraft", "MaximumBlocksPerCraft"),
    ("Game", "MaximumPlayerShips", "MaximumPlayerShips"),
    ("Game", "MaximumPlayerStations", "MaximumPlayerStations"),
    ("Game", "BoardingAllowed", "BoardingAllowed"),
    ("Game", "sameStartSector", "SameStartSector"),
    ("Game", "motd", "Motd"),
    ("System", "saveInterval", "SaveInterval"),
    ("System", "workerThreads", "WorkerThreads"),
    ("System", "generatorThreads", "GeneratorThreads"),
    ("System", "scriptBackgroundThreads", "ScriptBackgroundThreads"),
    ("System", "aliveSectorsPerPlayer", "AliveSectorsPerPlayer"),
    ("System", "backups", "Backups"),
    ("Networking", "isListed", "Listed"),
    ("Networking", "rconPassword", "RconPassword"),
    ("Administration", "name", "Hostname"),
    ("Administration", "description", "Description"),
    ("Administration", "password", "PrivatePassword"),
    ("Administration", "pausable", "Pausable"),
    ("Administration", "accessListMode", "AccessListMode"),
};

var vars = ThisService.Variables;
var lines = (File.Exists(ini) ? File.ReadAllLines(ini) : new string[0]).ToList();
string seedVar = vars.ContainsKey("Seed") ? Convert.ToString(vars["Seed"]).Trim() : "";
string fileSeed = null;
{
    string section = "";
    foreach (var l in lines)
    {
        var s = Regex.Match(l, @"^\s*\[(.+)\]\s*$");
        if (s.Success) { section = s.Groups[1].Value; continue; }
        if (section == "Game" && l.StartsWith("Seed=")) fileSeed = l.Substring(5).Trim();
    }
}

// The galaxy is generated from its seed: an existing galaxy keeps the seed it was made with. A new galaxy without a
// seed gets a random one (a blank seed would give every new server the same galaxy).
string newSeedVar = null;
string seed;
if (started && fileSeed != null)
{
    seed = fileSeed;
    if (seedVar != fileSeed)
    {
        newSeedVar = fileSeed;
        ScriptConsole.WriteLine((object)("The galaxy already exists; it keeps its seed " + fileSeed + ". Delete galaxies/avorion_galaxy for a new galaxy with another seed."));
    }
}
else if (seedVar.Length > 0) seed = seedVar;
else
{
    const string chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    var rng = new Random();
    seed = new string(Enumerable.Range(0, 10).Select(_ => chars[rng.Next(chars.Length)]).ToArray());
    newSeedVar = seed;
    ScriptConsole.WriteLine((object)("New galaxy: random seed " + seed + "."));
}

string Value(string variable)
{
    if (variable == "Seed") return seed;
    return vars.ContainsKey(variable) ? Convert.ToString(vars[variable]) ?? "" : null;
}

int changed = 0;
foreach (var m in managed)
{
    string value = Value(m.Variable);
    if (value == null) continue;
    value = value.Replace("\r", " ").Replace("\n", " ");
    // Find the section, then the key inside it.
    int start = lines.FindIndex(l => Regex.IsMatch(l, @"^\s*\[" + Regex.Escape(m.Section) + @"\]\s*$"));
    if (start < 0) { lines.Add("[" + m.Section + "]"); start = lines.Count - 1; }
    int end = lines.FindIndex(start + 1, l => Regex.IsMatch(l, @"^\s*\[.+\]\s*$"));
    if (end < 0) end = lines.Count;
    int at = lines.FindIndex(start + 1, end - start - 1, l => l.StartsWith(m.Key + "="));
    string line = m.Key + "=" + value;
    if (at < 0) { lines.Insert(end, line); changed++; }
    else if (lines[at] != line) { lines[at] = line; changed++; }
}
if (changed > 0)
{
    bool iniExisted = File.Exists(ini);
    File.WriteAllText(ini, string.Join("\n", lines) + "\n");
    if (!iniExisted) Own(ini);
    ScriptConsole.WriteLine((object)("Applied " + changed + " config editor setting(s) to server.ini."));
}

if (newSeedVar != null)
{
    var service = await GameServiceManager.GetAsync(ThisService.ServiceId);
    var updated = new TCAdminVars();
    foreach (var pair in service.Variables ?? new TCAdminVars()) updated[pair.Key] = pair.Value;
    updated["Seed"] = newSeedVar;
    service.Variables = updated;
    GameServiceManager.TCAdminDbContext.Entry(service).State = EntityState.Modified;
    await GameServiceManager.SaveChangesAsync(ThisCancellationToken);
}

// The Workshop mod list (the Workshop page adds and removes entries).
string modconfig = Path.Combine(galaxy, "modconfig.lua");
if (!File.Exists(modconfig))
{
    File.WriteAllText(modconfig, "modLocation = \"\"\nforceEnabling = false\n\nmods =\n{\n}\n\nallowed =\n{\n}\n");
    Own(modconfig);
    ScriptConsole.WriteLine((object)"Created an empty modconfig.lua.");
}

// Linux: the script runs as root; a file or folder it creates belongs to the service user (root-owned files are
// hidden in the file manager and the server cannot write them).
void Own(string path)
{
    if (System.OperatingSystem.IsLinux()) Globals.OperatingSystem.SetFileOwnerAutoDetect(path);
}

