using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Graceful stop: the /stop console command saves the galaxy (sectors, factions, players) and shuts the server down.
// Sent through the same path as a command typed in the console; the panel then finds the server already stopped.
const int maxWaitSeconds = 120;
var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
var binary = System.OperatingSystem.IsWindows() ? "AvorionServer.exe" : "AvorionServer";

List<int> ServerPids()
{
    var pids = new List<int>();
    if (System.OperatingSystem.IsWindows())
    {
        foreach (var p in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(binary)))
        {
            try { if (p.MainModule.FileName.StartsWith(root, StringComparison.OrdinalIgnoreCase)) pids.Add(p.Id); }
            catch { } // exited meanwhile
        }
        return pids;
    }
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var exe = new FileInfo(Path.Combine(dir, "exe")).LinkTarget ?? "";
            if (exe.StartsWith(root, StringComparison.Ordinal) && Path.GetFileName(exe) == binary) pids.Add(pid);
        }
        catch { } // processes of other users, or gone meanwhile
    }
    return pids;
}

if (ServerPids().Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    return;
}
await ServiceManagerService.SendConsoleInput(ThisService.ServiceId, "/stop");
ScriptConsole.WriteLine((object)"Asked the server to save the galaxy and shut down (/stop).");
for (var second = 1; second <= maxWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (ServerPids().Count == 0)
    {
        ScriptConsole.WriteLine((object)("The server exited after " + second + " s."));
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not exit within " + maxWaitSeconds + " s; the panel stops it now."));

