using System;
using System.IO;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Avorion servers download their Workshop mods themselves: the ids listed in the galaxy's modconfig.lua
// (mods = { {workshopid = "<id>"}, ... }) are downloaded and loaded when the server starts, and players who join
// get them from the Workshop. Add this item to the list.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string modConfigPath = Path.Combine((string)ThisService.RootDirectory, "galaxies", "avorion_galaxy", "modconfig.lua");
const string emptyModConfig = "modLocation = \"\"\nforceEnabling = false\n\nmods =\n{\n}\n\nallowed =\n{\n}\n";

string ReadModConfig()
{
    if (!File.Exists(modConfigPath)) return emptyModConfig;
    string t = File.ReadAllText(modConfigPath);
    // No mods table (an edited or truncated file): add one.
    if (!Regex.IsMatch(t, "(?m)^\\s*mods\\s*=\\s*\\{")) t = t.TrimEnd() + "\n\nmods =\n{\n}\n";
    return t;
}

void WriteModConfig(string t)
{
    Directory.CreateDirectory(Path.GetDirectoryName(modConfigPath));
    File.WriteAllText(modConfigPath, t);
    if (System.OperatingSystem.IsLinux()) Globals.OperatingSystem.SetFileOwnerAutoDetect(modConfigPath);
}

// open = index after the "{" of "mods = {", close = index of its matching "}" (Lua comments are skipped).
void FindModsTable(string t, out int open, out int close)
{
    var m = Regex.Match(t, "(?m)^\\s*mods\\s*=\\s*\\{");
    open = m.Index + m.Length;
    int depth = 1, i = open;
    for (; i < t.Length && depth > 0; i++)
    {
        if (t[i] == '-' && i + 1 < t.Length && t[i + 1] == '-') { while (i < t.Length && t[i] != '\n') i++; continue; }
        if (t[i] == '"') { i++; while (i < t.Length && t[i] != '"') i++; continue; }
        if (t[i] == '{') depth++;
        else if (t[i] == '}') depth--;
    }
    if (depth != 0) throw new Exception("modconfig.lua has no closing } for the mods table; fix the file in the file manager.");
    close = i - 1;
}


string text = ReadModConfig();
int open, close;
FindModsTable(text, out open, out close);
string table = text.Substring(open, close - open);
if (Regex.IsMatch(table, "workshopid\\s*=\\s*\"" + fileId + "\""))
{
    ScriptConsole.WriteLine((object)("Workshop item " + fileId + " is already in modconfig.lua."));
    return;
}
// Lua allows a comma after the last entry; make sure the entry before ours has one.
string before = text.Substring(0, close).TrimEnd();
string sep = before.EndsWith("}") ? "," : "";
string inserted = before + sep + "\n    {workshopid = \"" + fileId + "\"},\n" + text.Substring(close);
WriteModConfig(inserted);
ScriptConsole.WriteLine((object)("Added Workshop item " + fileId + " to modconfig.lua. The server downloads and loads it the next time it starts."));

