string table = text.Substring(open, close - open);
string cleaned = Regex.Replace(table, "[ \\t]*\\{\\s*workshopid\\s*=\\s*\"" + fileId + "\"\\s*\\}\\s*,?[ \\t]*\\r?\\n?", "");
if (cleaned == table)
{
    ScriptConsole.WriteLine((object)("Workshop item " + fileId + " was not in modconfig.lua."));
    return;
